"""Generate experiments/analysis/power_analysis.md (planning calculation under assumed variances)."""
from pathlib import Path

from plantpulse.config import REPO_ROOT
from plantpulse.stats.power import power_table

t = power_table()
out = REPO_ROOT / "experiments" / "analysis" / "power_analysis.md"
piv = t.pivot_table(index=["design", "true_ratio"], columns="cv_unit", values="power")
lines = [
    "# Power analysis (planning calculation)",
    "",
    "Generated by `scripts/run_power_analysis.py`. Simulation under **assumed** variance components:",
    "within-pod plant CV 15 %, run CV 10 %, pod CV 5 %, and between-unit (pod-run) CV as tabulated.",
    "Six plants per pod; analysis on log pod-run means. These assumptions will be replaced by the",
    "variance components estimated in uniformity trials U1-U2. Nothing here is an experimental result.",
    "",
    "`true_ratio` = true treatment mean / control mean for the endpoint.",
    "",
    "| Design | True ratio | " + " | ".join(f"power @ CV_unit {100 * c:.0f} %" for c in piv.columns) + " |",
    "|---|---|" + "---|" * len(piv.columns),
]
for (design, ratio), row in piv.iterrows():
    lines.append(f"| {design} | {ratio:.2f} | " + " | ".join("-" if v != v else f"{v:.2f}" for v in row) + " |")
lines += [
    "",
    "## Reading the table",
    "",
    "- Study A: a single 4x4 Latin square (6 residual df, Dunnett-adjusted) is adequate only for large",
    "  effects. Smaller effects need a second square (8 runs) or are reported as estimates with wide intervals.",
    "- Study C: the 10 % energy-per-biomass target needs low unit-to-unit variability and more than four runs",
    "  for conventional power; the run count for Study C is fixed only after U1-U2.",
    "- Monte Carlo error on each entry is about +/- 0.02 to 0.04.",
]
out.write_text("\n".join(lines) + "\n")
print(out.read_text())
